{
  "packet_id": "H6-T04-1",
  "claim_id": "C023",
  "status": "UNSUPPORTED",
  "claim": {
    "component_id": "C023.component",
    "value": "Exposure should stop early only under predefined harm criteria.",
    "scope": "A necessary condition for early exposure stopping in the proposed comparison; the harm criteria are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly makes predefined harm criteria necessary for early exposure stopping."
    }
  },
  "signal_basis": {
    "component_id": "C023.signal_basis",
    "value": "The release comparison measures first-publication rates within a common window, publication timing, retention at the targeted checkpoint and predefined guardrails. Eligible accounts are randomized where feasible, with identical measurement and predeclared sample and follow-up limits.",
    "scope": "The proposed comparison of the selected change with the existing experience.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison design, observation limits and measured outcomes, including the feasibility qualification on randomization."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C023.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The judgment is not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "Predeclared limits can protect a comparison from opportunistic stopping, and guardrail observations can justify stopping for harm. Neither establishes that predefined harm criteria are the only permissible grounds for stopping exposure early. The mapping states that exclusive rule but supplies no warrant for its necessity, even assuming successful execution and the described signals.",
  "uncertainty": "The unspecified harm criteria do not determine this judgment; the unsupported element is the exclusivity of the stopping rule.",
  "anomalies": []
}
